package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.util.*;
import java.math.*;
import org.apache.commons.codec.digest.DigestUtils;
/** Explicit per-case consent, native assistant execution and human outcome grading. */
final class EvaluationRuns {
 private EvaluationRuns() {}
 static String proof(Store store,Store.Db db,Map<String,Object> row)throws Exception{return DigestUtils.sha256Hex(AiConsent.state(store,db,db.viewerId,"evaluation",row.get("suite_id").toString(),map("dataset_hash",row.get("dataset_hash"),"prompt_version",KnowledgeQuestions.PROMPT_VERSION))+":"+store.environment.getProperty("AI_KNOWLEDGE_ENABLED","false"));}
 static Map<String,Object> summary(Map<String,Object> data,Map<String,Object> run){int total=objects(data.get("cases")).size(),passed=0,failures=0,corrections=0;long sum=0,max=0;for(var item:objects(run.get("results"))){require(Boolean.TRUE.equals(item.get("attempted")),"Attempt every case before finishing");long latency=((Number)item.get("latency_ms")).longValue();sum+=latency;max=Math.max(max,latency);if(item.get("error")!=null){failures++;continue;}require(item.get("grade") instanceof Map<?,?>,"Grade every successful answer before finishing");var grade=object(item.get("grade"));if(Boolean.TRUE.equals(grade.get("correction_needed")))corrections++;if(Boolean.TRUE.equals(grade.get("acceptable")) && Boolean.TRUE.equals(grade.get("grounded")) && !Boolean.TRUE.equals(grade.get("correction_needed")) && latency<=((Number)data.get("latency_budget_ms")).longValue())passed++;}return map("total_cases",total,"attempted",total,"provider_failures",failures,"human_graded",total-failures,"passed",passed,"pass_percent",BigDecimal.valueOf(passed*100L).divide(BigDecimal.valueOf(total),2,RoundingMode.HALF_UP),"meets_declared_budget",passed*100>=total*((Number)data.get("minimum_pass_percent")).intValue(),"corrections",corrections,"mean_latency_ms",BigDecimal.valueOf(sum).divide(BigDecimal.valueOf(total),3,RoundingMode.HALF_UP),"max_latency_ms",max,"billed_tokens",null,"billed_cost",null,"qualification","Human judgment on declared cases; representative quality and competitive performance are unverified");}
 static Map<String,Object> command(Store store,Store.Db db,Map<String,Object> row,Map<String,Object> data,Map<String,Object> body)throws Exception{
  String operation=WorkJobs.text(body.get("operation"),12);require(Set.of("start","preview","ask","grade","finish","cancel").contains(operation),"Choose a supported evaluation operation");String id=WorkJobs.text(body.get("run_id"),32);require(id.matches("[0-9a-f]{32}"),"Use a 32-character run key");var runs=objects(data.get("runs"));Map<String,Object> run=null;for(var item:runs)if(item.get("run_id").equals(id))run=item;
  if(operation.equals("start")){require(body.keySet().equals(Set.of("operation","run_id")),"Provide operation and run_id");if(run!=null)return null;require(runs.size()<20,"Evaluation run capacity reached; create another suite version");var results=new ArrayList<Map<String,Object>>();for(int index=0;index<objects(data.get("cases")).size();index++)results.add(map("case",index,"attempted",false,"answer",null,"error",null,"latency_ms",null,"grade",null));String cohort=row.get("cohort").equals("held_out")?(runs.isEmpty()?"held_out":"regression"):"development";runs.add(map("run_id",id,"state","open","cohort",cohort,"created",now(),"provider_alias",store.environment.getProperty("AI_CONNECTOR_ALIAS",""),"model",store.environment.getProperty("AI_MODEL",""),"prompt_version",KnowledgeQuestions.PROMPT_VERSION,"dataset_hash",row.get("dataset_hash"),"proof",proof(store,db,row),"results",results,"summary",null));return null;}
  if(run==null)throw new Failure(404,"Evaluation run not found");
  if(Set.of("finish","cancel").contains(operation)){require(body.keySet().equals(Set.of("operation","run_id")),"Provide operation and run_id");require(run.get("state").equals("open"),"Evaluation run is closed");if(operation.equals("finish")){run.put("summary",summary(data,run));run.put("state","completed");}else run.put("state","cancelled");SecurityEvents.record(db,db.viewerId,db.viewerId,"ai.evaluation_closed",map("suite_id",row.get("suite_id"),"run_id",id,"state",run.get("state")));return null;}
  int index=AssistantEvaluations.integer(body.get("case"),0,objects(data.get("cases")).size()-1);var item=objects(data.get("cases")).get(index);var result=objects(run.get("results")).get(index);
  if(operation.equals("grade")){require(body.keySet().equals(Set.of("operation","run_id","case","acceptable","grounded","correction_needed","rationale")),"Provide the grade fields only");require(run.get("state").equals("open") && Boolean.TRUE.equals(result.get("attempted")) && result.get("error")==null,"Grade an answered case in an open run");for(String key:List.of("acceptable","grounded","correction_needed"))require(body.get(key) instanceof Boolean,"Use boolean grades");result.put("grade",map("acceptable",body.get("acceptable"),"grounded",body.get("grounded"),"correction_needed",body.get("correction_needed"),"rationale",WorkJobs.text(body.get("rationale"),2000),"reviewed_at",now()));return null;}
  boolean asking=operation.equals("ask");require(body.keySet().equals(asking?Set.of("operation","run_id","case","preview_token","allow_external"):Set.of("operation","run_id","case")),"Provide the reviewed case fields only");if(asking){require(Boolean.TRUE.equals(body.get("allow_external")),"Confirm sending the reviewed source and question");if(Boolean.TRUE.equals(result.get("attempted")))return null;}require(run.get("state").equals("open") && !Boolean.TRUE.equals(result.get("attempted")),"Preview an unattempted case in an open run");if(!run.get("proof").equals(proof(store,db,row)))throw new Failure(409,"Provider or authority changed; start another run");var nativePreview=KnowledgeQuestions.submit(store,db,item.get("article_id").toString(),map("operation","preview","question",item.get("question")));String state=DigestUtils.sha256Hex(run.get("proof")+":"+id+":"+index+":"+JSON.writeValueAsString(map("source",nativePreview.get("source"),"question",item.get("question"))));if(!asking){var preview=map("run_id",id,"case",index,"source",nativePreview.get("source"),"question",item.get("question"),"provider_alias",run.get("provider_alias"),"model",run.get("model"));preview.putAll(AiConsent.issue(store,state));return preview;}AiConsent.verify(store,body.get("preview_token"),state);long started=System.nanoTime();var answer=KnowledgeQuestions.submit(store,db,item.get("article_id").toString(),map("operation","ask","question",item.get("question"),"preview_token",nativePreview.get("preview_token"),"allow_external",true));result.put("latency_ms",(System.nanoTime()-started)/1000000);result.put("attempted",true);result.put("answer",answer.get("answer"));result.put("error",answer.get("error"));return null;
 }
}
